define("theme_learnlingo/colour_settings", [], function() { 'use strict'; const normaliseHex = (value) => { const match = /^#?([a-f0-9]{3}|[a-f0-9]{6})$/i.exec(value.trim()); if (!match) { return null; } let hex = match[1].toUpperCase(); if (hex.length === 3) { hex = hex.split('').map((digit) => digit + digit).join(''); } return '#' + hex; }; const contrastInk = (value) => { const hex = normaliseHex(value); if (!hex) { return '#FFFFFF'; } const channels = [1, 3, 5].map((i) => { const srgb = parseInt(hex.slice(i, i + 2), 16) / 255; return srgb <= 0.04045 ? srgb / 12.92 : Math.pow((srgb + .055) / 1.055, 2.4); }); const luminance = .2126 * channels[0] + .7152 * channels[1] + .0722 * channels[2]; return luminance > .179 ? '#182231' : '#FFFFFF'; }; const bind = (container) => { if (container.dataset.colourBound === '1') { return; } container.dataset.colourBound = '1'; const input = container.querySelector('.ll-colour-picker__hex'); const native = container.querySelector('.ll-colour-picker__native'); const preview = container.querySelector('[data-colour-preview]'); const error = container.querySelector('[data-colour-error]'); const swatches = Array.from(container.querySelectorAll('[data-colour]')); const reset = container.querySelector('[data-colour-reset]'); if (!input || !native || !preview || !reset) { return; } const refresh = (showError = false) => { const raw = input.value.trim(); const hex = normaliseHex(raw); const valid = Boolean(hex) || raw === '' || (typeof CSS !== 'undefined' && CSS.supports('color', raw)); const active = hex || (valid && raw ? raw : container.dataset.default); preview.style.backgroundColor = active; preview.style.setProperty('--ll-picker-preview-ink', contrastInk(hex || container.dataset.default)); if (hex) { native.value = hex; } input.setAttribute('aria-invalid', showError && !valid ? 'true' : 'false'); if (error) { error.hidden = !showError || valid; } swatches.forEach((button) => { button.setAttribute('aria-pressed', hex === button.dataset.colour ? 'true' : 'false'); button.style.setProperty('--ll-picker-swatch-ink', contrastInk(button.dataset.colour)); }); }; const select = (colour) => { input.value = colour; refresh(); input.dispatchEvent(new Event('change', {bubbles: true})); }; input.addEventListener('input', () => refresh(true)); input.addEventListener('blur', () => { const hex = normaliseHex(input.value); if (hex) { input.value = hex; } refresh(true); }); native.addEventListener('input', () => select(native.value.toUpperCase())); swatches.forEach((button) => button.addEventListener('click', () => select(button.dataset.colour))); reset.addEventListener('click', () => select(container.dataset.default)); refresh(); }; return { init: () => document.querySelectorAll('[data-ll-colour-picker]').forEach(bind), }; });
